INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1057, 147, 1, 'ما هي الأذكار المطلقة؟', 0, '(ص247)', '', '', 'ما هي الأذكار المطلقة', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1390, 147, 2, 'هي المأثورة التي وردت عن الشارع، ولم تُربَط بسبب، ولا وظيفةٍ، ولا مناسبة، ولا هيئة، ولا عدد، ولا وقت.', 0, 'ما هي الأذكار المطلقة؟ (ص247)', '', '', 'هي المأثورة التي وردت عن الشارع ولم تربط بسبب ولا وظيفة ولا مناسبة ولا هيئة ولا عدد ولا وقت', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1391, 147, 3, 'من أنواع الذكر المطلق: تلاوة القرآن الكريم، والتهليل، والتكبير، والتسبيح، والتحميد، والحَوْلَقة، والاستغفار، والحسبلة.', 0, 'ما هي الأذكار المطلقة؟ (ص247)', '', '', 'من أنواع الذكر المطلق تلاوة القرآن الكريم والتهليل والتكبير والتسبيح والتحميد والحولقة والاستغفار والحسبلة', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1392, 147, 4, 'ومنها: الأدعية المطلقة.', 0, 'ما هي الأذكار المطلقة؟ (ص247)', '', '', 'ومنها الأدعية المطلقة', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1393, 147, 5, 'ومنها: الصلاة على النبي ﷺ، وبخاصَّة يوم الجمعة.', 0, 'ما هي الأذكار المطلقة؟ (ص247)', '', '', 'ومنها الصلاة على النبي وبخاصة يوم الجمعة', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1394, 147, 6, 'ومنها: دعاء الإنسان لوالِدَيْهِ، وأهلِهِ، وذُرِّيَّتِهِ، وأشايخِهِ، وإخوانِهِ في الله، وسائرِ المسلمين.', 0, 'ما هي الأذكار المطلقة؟ (ص247)', '', '', 'ومنها دعاء الإنسان لوالديه وأهله وذريته وأشايخه وإخوانه في الله وسائر المسلمين', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1395, 147, 7, 'الورد:', 0, '(ص248)', '', '', 'الورد', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1396, 147, 8, 'الورد أو الحزب هو مجموعة من الأذكار يلتزمها الذَّاكِرُ، ويواظِب عليها تَقَرُّبًا إلى الله تعالى، وهو تطوع لم يَفْرِضْه الله عليه.', 0, 'الورد: (ص248)', '', '', 'الورد أو الحزب هو مجموعة من الأذكار يلتزمها الذاكر ويواظب عليها تقربا إلى الله تعالى وهو تطوع لم يفرضه الله عليه', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1397, 147, 9, 'وينصرف الوِرْدُ عند الإطلاق إلى تلاوةِ القرآن الكريم، فهو أهمُّ وِرْدٍ يُطالَب المسلمُ بالمحافظةِ عليه يوميًّا؛ كي لا يكونَ ممن اتخذ القرآنَ مهجورًا، وأفضلُ أحوالِ الوِرْدِ القرآني اليومي أن يكونَ في صلاةِ قيامِ الليل.', 0, 'الورد: (ص248)', '', '', 'وينصرف الورد عند الإطلاق إلى تلاوة القرآن الكريم فهو أهم ورد يطالب المسلم بالمحافظة عليه يوميا كي لا يكون ممن اتخذ القرآن مهجورا وأفضل أحوال الورد القرآني اليومي أن يكون في صلاة قيام الليل', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1398, 147, 10, 'وقد شاع على ألسِنَةِ السَّلَفِ الصَّالِح ومن تَبِعَهم من الخَلَفِ استعمالُ كلمة (الورد) أو (الحزب) منسوبةً إلى الشخص المعين، مقصودًا بها في الأصل وردُ القرآنِ الكريمِ الذي يُتلى في قيامِ الليل.', 0, 'الورد: (ص248)', '', '', 'وقد شاع على ألسنة السلف الصالح ومن تبعهم من الخلف استعمال كلمة الورد أو الحزب منسوبة إلى الشخص المعين مقصودا بها في الأصل ورد القرآن الكريم الذي يتلى في قيام الليل', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1399, 147, 11, 'ومن العلماء من ذهب إلى أنَّ (الحزبَ) مختصٌّ بالقرآن الكريم، والوِرْدَ عامٌّ في كُلِّ الأذكار.', 0, 'الورد: (ص248)', '', '', 'ومن العلماء من ذهب إلى أن الحزب مختص بالقرآن الكريم والورد عام في كل الأذكار', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1400, 147, 12, 'ما هو «الورد الشخصي»؟', 0, '(ص249)', '', '', 'ما هو «الورد الشخصي»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1401, 147, 13, 'لقد أمَرَنَا اللهُ تعالى بالإكثار من ذكره، قال تعالى: ﴿وَٱذۡكُرُواْ ٱللَّهَ كَثِيرٗا﴾، وقال ﷺ: «استكثروا من الباقيات الصالحات» الحديث، وقال ﷺ: «أكثروا من شهادة أن لا إله إلا الله» الحديث، وقال ﷺ: «طُوبَى لِمن وَجَدَ في صحيفته استغفارًا كثيرًا»، وقال ﷺ: «أكثِروا من غرس الجنة» الحديث، وقال: «أكثروا من قول: لا حولَ ولا قوَّةَ إلَّا بالله» الحديث.', 0, 'ما هو «الورد الشخصي»؟ (ص249)', '', '', 'لقد أمرنا الله تعالى بالإكثار من ذكره قال تعالى ﴿وٱذۡكروا ٱلله كثيرا﴾ وقال «استكثروا من الباقيات الصالحات» الحديث وقال «أكثروا من شهادة أن لا إله إلا الله» الحديث وقال «طوبى لمن وجد في صحيفته استغفارا كثيرا» وقال «أكثروا من غرس الجنة» الحديث وقال «أكثروا من قول لا حول ولا قوة إلا بالله» الحديث', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1402, 147, 14, 'فهذه الأذكارُ المطلقة رغم أننا أُمِرْنَا بالإكثار منها؛ فإنَّ بعضَ الناس قد يهجرونها ويغفلون عنها، بخلافِ الأذكار الموظَّفة؛ فإنَّها راتبة تتكرر مناسباتها، فيحافظ العبدُ عليها، ومن هنا يأتي (الورد الشخصي)؛ ليخصِّصَ فيه العبدُ وقتًا ما لكلِّ واحدٍ من الأذكار المُطلَقَةِ، أو لِكُلِّها مجتمعةً، ولا بأسَ أن يُحدِّد لكلٍّ منها عددًا؛ كي (يُكثِرَ) منها في جلسة (الورد الشخصي)، وينتقي من صيغها، ويتنقل بينها من وقتٍ إلى آخرَ.', 0, 'ما هو «الورد الشخصي»؟ (ص249–250)', '', '', 'فهذه الأذكار المطلقة رغم أننا أمرنا بالإكثار منها فإن بعض الناس قد يهجرونها ويغفلون عنها بخلاف الأذكار الموظفة فإنها راتبة تتكرر مناسباتها فيحافظ العبد عليها ومن هنا يأتي الورد الشخصي ليخصص فيه العبد وقتا ما لكل واحد من الأذكار المطلقة أو لكلها مجتمعة ولا بأس أن يحدد لكل منها عددا كي يكثر منها في جلسة الورد الشخصي وينتقي من صيغها ويتنقل بينها من وقت إلى آخر', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1403, 147, 15, 'من خصائص (الورد الشخصي) أنه لا يرتبط بوقتٍ ولا عددٍ مُحدَّدَيْنِ:', 0, '(ص250)', '', '', 'من خصائص الورد الشخصي أنه لا يرتبط بوقت ولا عدد محددين', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1404, 147, 16, 'وإنَّما يقومُ كلُّ إنسانٍ -على حِدَةٍ- بتحديد الوقت والعدد الذي يناسب ظروفَه الشخصية، دون أن يُلزِمَ بها غيره.', 0, 'من خصائص (الورد الشخصي) أنه لا يرتبط بوقتٍ ولا عددٍ مُحدَّدَيْنِ: (ص250)', '', '', 'وإنما يقوم كل إنسان -على حدة- بتحديد الوقت والعدد الذي يناسب ظروفه الشخصية دون أن يلزم بها غيره', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1405, 147, 17, 'يختص الورد الشخصي بالذكر المطلق دون المُقَيَّد:', 0, '(ص250)', '', '', 'يختص الورد الشخصي بالذكر المطلق دون المقيد', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1406, 147, 18, 'فإنَّ الذكر المقيَّد بلفظٍ وعددٍ وهيئةٍ وزمانٍ ومكانٍ خارجٌ تمامًا عن دائرةِ الوِردِ الشخصي؛ لأنَّ هذا التقييد مِن خواصِّ الشارع، وإلَّا وَقَعَ المُكَلَّفُ في البدعة.', 0, 'يختص الورد الشخصي بالذكر المطلق دون المُقَيَّد: (ص250)', '', '', 'فإن الذكر المقيد بلفظ وعدد وهيئة وزمان ومكان خارج تماما عن دائرة الورد الشخصي لأن هذا التقييد من خواص الشارع وإلا وقع المكلف في البدعة', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1407, 147, 19, 'والأصلُ في الورد الشخصي التزامُ المأثورِ عن النبي ﷺ، ويُباحُ غيرُ المأثور بشرط أن لا يجعلَه ديدنَه وشعارَه كأنَّه سُنَّة، ولا يهجر المأثور انشغالًا به.', 0, 'يختص الورد الشخصي بالذكر المطلق دون المُقَيَّد: (ص250)', '', '', 'والأصل في الورد الشخصي التزام المأثور عن النبي ويباح غير المأثور بشرط أن لا يجعله ديدنه وشعاره كأنه سنة ولا يهجر المأثور انشغالا به', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1408, 147, 20, 'وقد تواتر عن العلماء والصالحين منذُ الصدرِ الأوَّلِ إلى يومنا هذا أنه كان لِكُلٍّ منهم أورادٌ يُحافَظُ عليها حتى في أحرجِ أوقاتِ حياته، ولا يُفَرَّطُ فيها بأيَّةِ حالٍ.', 0, 'يختص الورد الشخصي بالذكر المطلق دون المُقَيَّد: (ص251)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1409, 147, 21, 'الحياة أوراد', 0, '(ص252)', '', '', 'الحياة أوراد', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1410, 147, 22, 'من أرادَ أن يدخلَ الجنَّةَ بغير حساب؛ فَلْيستغرِقْ أوقاتَه في الطَّاعة، وذكرِ الله، ومن أرادَ أن تترجَّحَ كِفَّةُ حسناتِه، وتثقلَ موازينُ خيراتِه، فلْيستوعِبْ في الطاعة أكثرَ أوقاتِه، ويكفي للتدليل على هذا أنَّ الله سبحانه خاطَبَ أقربَ عبادِه إليه، وأرفعَهم درجةً لديه ﷺ، فقال: ﴿وَٱذۡكُرِ ٱسۡمَ رَبِّكَ بُكۡرَةٗ وَأَصِيلٗا ۝ وَمِنَ ٱلَّيۡلِ فَٱسۡجُدۡ لَهُۥ وَسَبِّحۡهُ لَيۡلٗا طَوِيلًا﴾ [الإنسان: ٢٥، ٢٦]، وقال تعالى: ﴿وَسَبِّحۡ بِحَمۡدِ رَبِّكَ قَبۡلَ طُلُوعِ ٱلشَّمۡسِ وَقَبۡلَ ٱلۡغُرُوبِ ۝ وَمِنَ ٱلَّيۡلِ فَسَبِّحۡهُ وَأَدۡبَٰرَ ٱلسُّجُودِ﴾ [ق: ٣٩، ٤٠]، وقال تعالى: ﴿وَمِنۡ ءَانَآيِٕ ٱلَّيۡلِ فَسَبِّحۡ وَأَطۡرَافَ ٱلنَّهَارِ لَعَلَّكَ تَرۡضَىٰ﴾ [طه: ١٣٠]، وقال عَزَّ وَجَلَّ: ﴿وَأَقِمِ ٱلصَّلَوٰةَ طَرَفَيِ ٱلنَّهَارِ وَزُلَفٗا مِّنَ ٱلَّيۡلِۚ إِنَّ ٱلۡحَسَنَٰتِ يُذۡهِبۡنَ ٱلسَّيِّـَٔاتِ﴾ [هود: ١١٤].', 0, 'الحياة أوراد. (ص252)', '', '', 'من أراد أن يدخل الجنة بغير حساب فليستغرق أوقاته في الطاعة وذكر الله ومن أراد أن تترجح كفة حسناته وتثقل موازين خيراته فليستوعب في الطاعة أكثر أوقاته ويكفي للتدليل على هذا أن الله سبحانه خاطب أقرب عباده إليه وأرفعهم درجة لديه فقال ﴿وٱذۡكر ٱسۡم ربك بكۡرة وأصيلا ۝ ومن ٱليۡل فٱسۡجدۡ لهۥ وسبحۡه ليۡلا طويلا﴾ الإنسان ٢٥ ٢٦ وقال تعالى ﴿وسبحۡ بحمۡد ربك قبۡل طلوع ٱلشمۡس وقبۡل ٱلۡغروب ۝ ومن ٱليۡل فسبحۡه وأدۡبر ٱلسجود﴾ ق ٣٩ ٤٠ وقال تعالى ﴿ومنۡ ءانآي ٱليۡل فسبحۡ وأطۡراف ٱلنهار لعلك ترۡضى﴾ طه ١٣٠ وقال عز وجل ﴿وأقم ٱلصلوة طرفي ٱلنهار وزلفا من ٱليۡلۚ إن ٱلۡحسنت يذۡهبۡن ٱلسيات﴾ هود ١١٤', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1411, 147, 23, 'ثُمَّ انظُرْ كيف وصَفَ الفائزين من عباده، وبماذا وصَفَهم؟ فقال تعالى: ﴿أَمَّنۡ هُوَ قَٰنِتٌ ءَانَآءَ ٱلَّيۡلِ سَاجِدٗا وَقَآئِمٗا يَحۡذَرُ ٱلۡأٓخِرَةَ وَيَرۡجُواْ رَحۡمَةَ رَبِّهِۦۗ قُلۡ هَلۡ يَسۡتَوِي ٱلَّذِينَ يَعۡلَمُونَ وَٱلَّذِينَ لَا يَعۡلَمُونَ﴾ [الزمر: ٩]، وقال تعالى: ﴿تَتَجَافَىٰ جُنُوبُهُمۡ عَنِ ٱلۡمَضَاجِعِ يَدۡعُونَ رَبَّهُمۡ خَوۡفٗا وَطَمَعٗا﴾ [السجدة: ١٦]، وقال عَزَّ وَجَلَّ: ﴿وَٱلَّذِينَ يَبِيتُونَ لِرَبِّهِمۡ سُجَّدٗا وَقِيَٰمٗا﴾ [الفرقان: ٦٤]، وقال عَزَّ وَجَلَّ: ﴿كَانُواْ قَلِيلٗا مِّنَ ٱلَّيۡلِ مَا يَهۡجَعُونَ ۝ وَبِٱلۡأَسۡحَارِ هُمۡ يَسۡتَغۡفِرُونَ﴾ [الذاريات: ١٧، ١٨]، وقال عَزَّ وَجَلَّ: ﴿فَسُبۡحَٰنَ ٱللَّهِ حِينَ تُمۡسُونَ وَحِينَ تُصۡبِحُونَ﴾ [الروم: ١٧]، وقال تعالى: ﴿وَلَا تَطۡرُدِ ٱلَّذِينَ يَدۡعُونَ رَبَّهُم بِٱلۡغَدَوٰةِ وَٱلۡعَشِيِّ يُرِيدُونَ وَجۡهَهُۥ﴾ [الأنعام: ٥٢].', 0, 'الحياة أوراد. (ص252–253)', '', '', 'ثم انظر كيف وصف الفائزين من عباده وبماذا وصفهم فقال تعالى ﴿أمنۡ هو قنت ءانآء ٱليۡل ساجدا وقآئما يحۡذر ٱلۡأخرة ويرۡجوا رحۡمة ربهۦۗ قلۡ هلۡ يسۡتوي ٱلذين يعۡلمون وٱلذين لا يعۡلمون﴾ الزمر ٩ وقال تعالى ﴿تتجافى جنوبهمۡ عن ٱلۡمضاجع يدۡعون ربهمۡ خوۡفا وطمعا﴾ السجدة ١٦ وقال عز وجل ﴿وٱلذين يبيتون لربهمۡ سجدا وقيما﴾ الفرقان ٦٤ وقال عز وجل ﴿كانوا قليلا من ٱليۡل ما يهۡجعون ۝ وبٱلۡأسۡحار همۡ يسۡتغۡفرون﴾ الذاريات ١٧ ١٨ وقال عز وجل ﴿فسبۡحن ٱلله حين تمۡسون وحين تصۡبحون﴾ الروم ١٧ وقال تعالى ﴿ولا تطۡرد ٱلذين يدۡعون ربهم بٱلۡغدوة وٱلۡعشي يريدون وجۡههۥ﴾ الأنعام ٥٢', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1412, 147, 24, 'فهذا كله يبين لكَ أنَّ الطريقَ إلى الله تعالى مراقبةُ الأوقاتِ وعِمارتُها بالأوراد على سبيل الدوام.', 0, 'الحياة أوراد. (ص253)', '', '', 'فهذا كله يبين لك أن الطريق إلى الله تعالى مراقبة الأوقات وعمارتها بالأوراد على سبيل الدوام', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1413, 147, 25, 'الحثُّ على المداومةِ على الأوراد', 0, '(ص254)', '', '', 'الحث على المداومة على الأوراد', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1414, 147, 26, 'لقد كان رسولُ الله ﷺ يَحُثُّ على المداومةِ على الأعمال، ويفعل ذلك، ويأمر به أصحابَه رضي الله عنهم، ولو كان العملُ يسيرًا قليلًا؛ فإنَّ العبرةَ باستدامةِ العمل، والثباتِ عليه.', 0, 'الحث على المداومة على الأوراد. (ص254)', '', '', 'لقد كان رسول الله يحث على المداومة على الأعمال ويفعل ذلك ويأمر به أصحابه رضي الله عنهم ولو كان العمل يسيرا قليلا فإن العبرة باستدامة العمل والثبات عليه', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1415, 147, 27, 'عن القاسم بن محمدٍ، عن عائشةَ رضي الله عنها، قالت: قال رسولُ الله ﷺ: «أحبُّ الأعمالِ إلى اللهِ أدومُها وإن قلَّ»، قال: «وكانت عائشةُ إذا عَمِلَتْ العملَ لَزِمَتْه».', 0, 'الحث على المداومة على الأوراد. (ص254)', '', '', 'عن القاسم بن محمد عن عائشة رضي الله عنها قالت قال رسول الله «أحب الأعمال إلى الله أدومها وإن قل» قال «وكانت عائشة إذا عملت العمل لزمته»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1416, 147, 28, 'وكانت أمُّ المؤمنين عائشةُ رضي الله عنها تحافظ على صلاة الضحى ثمانيَ ركعاتٍ، وتقولُ: «لو نُشِرَ لي أبوايَ؛ ما تركتُهنَّ».', 0, 'الحث على المداومة على الأوراد. (ص254)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1417, 147, 29, 'وسُئلَتْ رضي الله عنها: أيُّ العمل كان أحبَّ إلى رسولِ الله ﷺ؟ فقالت: «الدائم».', 0, 'الحث على المداومة على الأوراد. (ص255)', '', '', 'وسئلت رضي الله عنها أي العمل كان أحب إلى رسول الله فقالت «الدائم»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1418, 147, 30, 'وعنها، قالت: «كان أحبُّ العملِ إلى رسولِ الله ﷺ الذي يَدُومُ عليه صاحِبُه».', 0, 'الحث على المداومة على الأوراد. (ص255)', '', '', 'وعنها قالت «كان أحب العمل إلى رسول الله الذي يدوم عليه صاحبه»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1419, 147, 31, 'إنَّ من ثمراتِ المداومةِ على العملِ الصالح: ترويضَ النفسِ على لزومِ الخيراتِ حتى تصير ديدَنَها، وعادَتَها، وصيانتَها عن الغفلة والباطل، وقد قيل: «نفسُك إن لم تشغلْها بالحق؛ شَغَلَتْكَ بالباطل».', 0, 'الحث على المداومة على الأوراد. (ص255)', '', '', 'إن من ثمرات المداومة على العمل الصالح ترويض النفس على لزوم الخيرات حتى تصير ديدنها وعادتها وصيانتها عن الغفلة والباطل وقد قيل «نفسك إن لم تشغلها بالحق شغلتك بالباطل»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1420, 147, 32, 'ولذلك تجد عند المداومين على الطاعة إقبالًا وصبرًا عليها، وحُبًّا لها، وتلَذُّذًا بها؛ كتلاوةِ كلام الله عَزَّ وَجَلَّ، وإدمانِ النَّظَرِ في المصحف الشريف، وكذا نوافل العبادات، فما بالُكَ بحالهم على المحافظة على الفرائض الواجبات؟!', 0, 'الحث على المداومة على الأوراد. (ص255)', '', '', 'ولذلك تجد عند المداومين على الطاعة إقبالا وصبرا عليها وحبا لها وتلذذا بها كتلاوة كلام الله عز وجل وإدمان النظر في المصحف الشريف وكذا نوافل العبادات فما بالك بحالهم على المحافظة على الفرائض الواجبات !', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1421, 147, 33, 'وقد قال الله تعالى في مدح الصالحين: ﴿ٱلَّذِينَ هُمۡ عَلَىٰ صَلَاتِهِمۡ دَآئِمُونَ﴾ [المعارج: ٢٣]، ثم ذكر لهم صفاتٍ أخرى، وختمها بقوله: ﴿وَٱلَّذِينَ هُمۡ عَلَىٰ صَلَاتِهِمۡ يُحَافِظُونَ ۝ أُوْلَٰٓئِكَ فِي جَنَّٰتٖ مُّكۡرَمُونَ﴾ [المعارج: ٣٤، ٣٥]، وقال في صفات المؤمنين: ﴿وَٱلَّذِينَ هُمۡ عَلَىٰ صَلَوَٰتِهِمۡ يُحَافِظُونَ ۝ أُوْلَٰٓئِكَ هُمُ ٱلۡوَٰرِثُونَ ۝ ٱلَّذِينَ يَرِثُونَ ٱلۡفِرۡدَوۡسَ هُمۡ فِيهَا خَٰلِدُونَ﴾ [المؤمنون: ٩–١١].', 0, 'الحث على المداومة على الأوراد. (ص255–256)', '', '', 'وقد قال الله تعالى في مدح الصالحين ﴿ٱلذين همۡ على صلاتهمۡ دآئمون﴾ المعارج ٢٣ ثم ذكر لهم صفات أخرى وختمها بقوله ﴿وٱلذين همۡ على صلاتهمۡ يحافظون ۝ أولئك في جنت مكۡرمون﴾ المعارج ٣٤ ٣٥ وقال في صفات المؤمنين ﴿وٱلذين همۡ على صلوتهمۡ يحافظون ۝ أولئك هم ٱلۡورثون ۝ ٱلذين يرثون ٱلۡفرۡدوۡس همۡ فيها خلدون﴾ المؤمنون ٩–١١', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1422, 147, 34, 'وما كان فريضةً على الإنسان فإنه فُرِضَ على الدوام، وقد قال تعالى في الحديث القدسي: «وما تقرَّبَ إليَّ عبدي بشيءٍ أحبَّ إليَّ مما افترضتُ عليه»، ثُمَّ قال عَزَّ وَجَلَّ: «ولا يزالُ عبدي يتقرَّبُ إليَّ بالنوافل حتَّى أُحِبَّه» الحديث، فقولُه: «ولا يزال» يُعَبِّرُ عن المداومةِ والمواظبةِ على الفرائض والنوافل، وقولُه: «حتى أُحِبَّه» إلخ، يُعَبِّرُ عن ثمرةِ هذه المداومة.', 0, 'الحث على المداومة على الأوراد. (ص256)', '', '', 'وما كان فريضة على الإنسان فإنه فرض على الدوام وقد قال تعالى في الحديث القدسي «وما تقرب إلي عبدي بشيء أحب إلي مما افترضت عليه» ثم قال عز وجل «ولا يزال عبدي يتقرب إلي بالنوافل حتى أحبه» الحديث فقوله «ولا يزال» يعبر عن المداومة والمواظبة على الفرائض والنوافل وقوله «حتى أحبه» إلخ يعبر عن ثمرة هذه المداومة', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1423, 147, 35, 'قال الحافظُ ابنُ حجر رحمه الله: «والحكمة في ذلك أنَّ المديمَ للعمل يلازم الخدمة، فيُكثِرُ الترددَ إلى بابِ الطاعة كلَّ وقتٍ ليُجازَى بالبِرِّ لكثرةِ ترددِه، فليس هو كمن لازمَ الخدمةَ -مثلًا- ثم انقطع، وأيضًا فالعاملُ إذا ترك العملَ صار كالمعرِضِ بعد الوَصْلِ؛ فيتعرضُ للذمِّ والجفاء، ومن ثَمَّ ورد الوعيدُ في حقِّ من حفظ القرآنَ ثُمَّ نَسِيَه». اهـ.', 0, 'الحث على المداومة على الأوراد. (ص256–257)', '', '', 'قال الحافظ ابن حجر رحمه الله «والحكمة في ذلك أن المديم للعمل يلازم الخدمة فيكثر التردد إلى باب الطاعة كل وقت ليجازى بالبر لكثرة تردده فليس هو كمن لازم الخدمة -مثلا- ثم انقطع وأيضا فالعامل إذا ترك العمل صار كالمعرض بعد الوصل فيتعرض للذم والجفاء ومن ثم ورد الوعيد في حق من حفظ القرآن ثم نسيه» اه', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1424, 147, 36, 'ويكفي في فضيلةِ المداومةِ أنَّ مَنْ دَاوَمَ على عملٍ صالحٍ ثُمَّ انقطعَ عنه بعذرٍ من مرضٍ أو سفرٍ أو نومٍ أو شيخوخةٍ؛ كُتِبَ له أجرُ ذلك العمل.', 0, 'الحث على المداومة على الأوراد. (ص257)', '', '', 'ويكفي في فضيلة المداومة أن من داوم على عمل صالح ثم انقطع عنه بعذر من مرض أو سفر أو نوم أو شيخوخة كتب له أجر ذلك العمل', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1425, 147, 37, 'فعن أبي موسى رضي الله عنه، قال رسولُ الله ﷺ: «إذا مَرِضَ العبدُ أو سافر؛ كَتَبَ اللهُ له من الأجر مثلَ ما كان يعملُ صحيحًا مُقيمًا».', 0, 'الحث على المداومة على الأوراد. (ص257)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1426, 147, 38, 'وقد رُوِيَ عَن شَقيقِ بْنِ عبد الله قال: مَرِضَ عبدُ الله بنُ مسعودٍ رضي الله عنه فَعُدْناه، فجعل يبكي، فعُوتِبَ، فقال: «إنِّي لا أبكي لأجلِ المرض؛ لأني سمعتُ رسولَ الله ﷺ يقول: «المرضُ كَفَّارة»، وإنَّما أبكي أنه أصابني على حالِ فترةٍ، ولم يُصبني في حالِ اجتهادٍ، إنه يُكتَبُ للعبد من الأجر إذا مَرِضَ ما كان يُكتَبُ له قبل أنْ يمرضَ، فمنعه منه المرضُ».', 0, 'الحث على المداومة على الأوراد. (ص257–258)', '', '', 'وقد روي عن شقيق بن عبد الله قال مرض عبد الله بن مسعود رضي الله عنه فعدناه فجعل يبكي فعوتب فقال «إني لا أبكي لأجل المرض لأني سمعت رسول الله يقول «المرض كفارة» وإنما أبكي أنه أصابني على حال فترة ولم يصبني في حال اجتهاد إنه يكتب للعبد من الأجر إذا مرض ما كان يكتب له قبل أن يمرض فمنعه منه المرض»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1427, 147, 39, 'وعن ابن عبَّاسٍ رضي الله عنهما قال: «إذا كان العبدُ في شبابه كثيرَ الصلاةِ كثيرَ الصيامِ والصدقة، ثم ضَعُفَ عمَّا كان يعمل في شبابه؛ أجرى اللهُ عَزَّ وَجَلَّ له ما كان يعمل في شبابه».', 0, 'الحث على المداومة على الأوراد. (ص258)', '', '', 'وعن ابن عباس رضي الله عنهما قال «إذا كان العبد في شبابه كثير الصلاة كثير الصيام والصدقة ثم ضعف عما كان يعمل في شبابه أجرى الله عز وجل له ما كان يعمل في شبابه»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1428, 147, 40, 'ومصداقُ ذلك في قوله تعالى: ﴿لَقَدۡ خَلَقۡنَا ٱلۡإِنسَٰنَ فِيٓ أَحۡسَنِ تَقۡوِيمٖ﴾ أي صورة، ﴿ثُمَّ رَدَدۡنَٰهُ أَسۡفَلَ سَٰفِلِينَ﴾ إلى أرذلِ العمرِ والخَرَف، ﴿إِلَّا ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ﴾ في وقتِ القوةِ والقدرة، فإنَّهم حالَ الكِبَر غيرُ منقوصين، وإن عجزوا عن الطاعات، أو أصابهم الخَرَفُ ﴿فَلَهُمۡ أَجۡرٌ غَيۡرُ مَمۡنُونٖ﴾ غيرُ منقطعٍ.', 0, 'الحث على المداومة على الأوراد. (ص258)', '', '', 'ومصداق ذلك في قوله تعالى ﴿لقدۡ خلقۡنا ٱلۡإنسن في أحۡسن تقۡويم﴾ أي صورة ﴿ثم رددۡنه أسۡفل سفلين﴾ إلى أرذل العمر والخرف ﴿إلا ٱلذين ءامنوا وعملوا ٱلصلحت﴾ في وقت القوة والقدرة فإنهم حال الكبر غير منقوصين وإن عجزوا عن الطاعات أو أصابهم الخرف ﴿فلهمۡ أجۡر غيۡر ممۡنون﴾ غير منقطع', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1429, 147, 41, 'احذرْ قُطَّاعَ الطريقِ إلى الله', 0, '(ص259)', '', '', 'احذر قطاع الطريق إلى الله', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1430, 147, 42, 'بالرغم من أنَّ الناسَ في تعاملهم مع «وسائل التواصل الاجتماعي» ينقسمون إلى ظالمٍ لنفسه، ومُقتصِدٍ، وسابقٍ بالخيراتِ بإذنِ الله، فإننا نُحَذِّرُ هنا من ظلمِ المرءِ نفسَه حين يهدرُ الساعاتِ الطِّوالَ (يتسكَّعُ) في هذه المواقع، ويُضَيِّعُ حزبَه القرآنيَّ ووِرْدَه الشخصيَّ، ومصالحَه الدنيوية، ويغرق في العالَمِ الافتراضي الذي يطغَى عليه «التقاطعُ الاجتماعي» بدلًا من «التواصل الحقيقي» الذي عزل الناسَ كلًّا في جزيرته بعيدًا عن التفاعل المباشر بينهم، وجعلهم صَرْعَى للخوض في «ماجَرَيَاتِ» الفَنِّ، والكرة، والسياسة، وجزئياتِ أحوال الناس، ومداخلِهم ومخارجِهم، وتوابعِ ذلك من هَذَيانِ التافهين، وأحوالِ النفوسِ المبطِلةِ الفارغةِ من ذكرِ الله تعالى واليومِ الآخِر.', 0, 'احذر قطّاع الطريق إلى الله. (ص259)', '', '', 'بالرغم من أن الناس في تعاملهم مع «وسائل التواصل الاجتماعي» ينقسمون إلى ظالم لنفسه ومقتصد وسابق بالخيرات بإذن الله فإننا نحذر هنا من ظلم المرء نفسه حين يهدر الساعات الطوال يتسكع في هذه المواقع ويضيع حزبه القرآني وورده الشخصي ومصالحه الدنيوية ويغرق في العالم الافتراضي الذي يطغى عليه «التقاطع الاجتماعي» بدلا من «التواصل الحقيقي» الذي عزل الناس كلا في جزيرته بعيدا عن التفاعل المباشر بينهم وجعلهم صرعى للخوض في «ماجريات» الفن والكرة والسياسة وجزئيات أحوال الناس ومداخلهم ومخارجهم وتوابع ذلك من هذيان التافهين وأحوال النفوس المبطلة الفارغة من ذكر الله تعالى واليوم الآخر', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1431, 147, 43, 'فعلى من عَجَزَ عن كبحِ جِماحِ نفسِه، وفشل في إدارةِ وقتِه بحزمٍ، وأيقن أنَّ «الغولَ العنكبوتيَّ» يلتهمُ عُمُرَه، ويفترسُ رأسَ مالِه، ويَصُدُّه عن ذكرِ الله وعن الصلاة؛ أن يتخلَّى عن جهازِه الذكي «المشؤوم»، ويستبدلَ جهازًا تقليديًّا بسيطًا لا يتيحُ له الولوجَ إلى عالَمِ «الإنترنت»؛ استدراكًا لما أضاعَ، واغتنامًا لما بَقِيَ من عُمُره ﴿وَأَنفِقُواْ مِن مَّا رَزَقۡنَٰكُم مِّن قَبۡلِ أَن يَأۡتِيَ أَحَدَكُمُ ٱلۡمَوۡتُ فَيَقُولَ رَبِّ لَوۡلَآ أَخَّرۡتَنِيٓ إِلَىٰٓ أَجَلٖ قَرِيبٖ فَأَصَّدَّقَ وَأَكُن مِّنَ ٱلصَّٰلِحِينَ ۝ وَلَن يُؤَخِّرَ ٱللَّهُ نَفۡسًا إِذَا جَآءَ أَجَلُهَاۚ وَٱللَّهُ خَبِيرُۢ بِمَا تَعۡمَلُونَ﴾ [المنافقون: ١٠، ١١]، وقال الله تعالى: ﴿ٱقۡتَرَبَ لِلنَّاسِ حِسَابُهُمۡ وَهُمۡ فِي غَفۡلَةٖ مُّعۡرِضُونَ ۝ مَا يَأۡتِيهِم مِّن ذِكۡرٖ مِّن رَّبِّهِم مُّحۡدَثٍ إِلَّا ٱسۡتَمَعُوهُ وَهُمۡ يَلۡعَبُونَ ۝ لَاهِيَةٗ قُلُوبُهُمۡ﴾ الآيات [الأنبياء: ١–٣].', 0, 'احذر قطّاع الطريق إلى الله. (ص260)', '', '', 'فعلى من عجز عن كبح جماح نفسه وفشل في إدارة وقته بحزم وأيقن أن «الغول العنكبوتي» يلتهم عمره ويفترس رأس ماله ويصده عن ذكر الله وعن الصلاة أن يتخلى عن جهازه الذكي «المشؤوم» ويستبدل جهازا تقليديا بسيطا لا يتيح له الولوج إلى عالم «الإنترنت» استدراكا لما أضاع واغتناما لما بقي من عمره ﴿وأنفقوا من ما رزقۡنكم من قبۡل أن يأۡتي أحدكم ٱلۡموۡت فيقول رب لوۡلآ أخرۡتني إلى أجل قريب فأصدق وأكن من ٱلصلحين ۝ ولن يؤخر ٱلله نفۡسا إذا جآء أجلهاۚ وٱلله خبيرۢ بما تعۡملون﴾ المنافقون ١٠ ١١ وقال الله تعالى ﴿ٱقۡترب للناس حسابهمۡ وهمۡ في غفۡلة معۡرضون ۝ ما يأۡتيهم من ذكۡر من ربهم محۡدث إلا ٱسۡتمعوه وهمۡ يلۡعبون ۝ لاهية قلوبهمۡ﴾ الآيات الأنبياء ١–٣', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1432, 147, 44, 'عن أبي هريرة رضي الله عنه أنَّ رسولَ الله ﷺ قال: «الدنيا ملعونةٌ، ملعونٌ ما فيها؛ إلَّا ذِكرَ الله، وما والاه، وعالِمًا أو متعلِّمًا».', 0, 'احذر قطّاع الطريق إلى الله. (ص260)', '', '', 'عن أبي هريرة رضي الله عنه أن رسول الله قال «الدنيا ملعونة ملعون ما فيها إلا ذكر الله وما والاه وعالما أو متعلما»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1433, 147, 45, 'لقد تَكَلَّمَ الإمامُ المُحَقِّقُ ابنُ القيِّمِ (ت: ٧٥١هـ) رحمه الله عن: «الأفكار الرديئة التي تجولُ في قلوبِ أكثرِ هذا الخلق...، ومنها الفكرُ في جزئياتِ أحوالِ الناس، وماجَرَيَاتِهم، ومداخلِهم ومخارجِهم، وتوابعِ ذلك من فِكَرِ النفوسِ المبطلةِ الفارغةِ من الله ورسولِه والدَّارِ الآخِرَةِ».', 0, 'احذر قطّاع الطريق إلى الله. (ص261)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1434, 147, 46, 'وحين تَكَلَّمَ عن طبقةِ العُبَّادِ الأخفياء الذين قال فيهم رسولُ الله ﷺ: «إنَّ اللهَ يُحِبُّ العبدَ التَّقِيَّ الغَنِيَّ الخَفِيَّ»، قال رحمه الله: «أهلُ هذه الطبقةِ، أثقلُ شيءٍ عليهم: البحثُ عن ماجَرَيَاتِ الناس، وطلبُ تَعَرُّفِ أحوالِهم، وأثقلُ ما على قلوبهم سماعُها، فَهُم مشغولون عنها بشأنهم، فإذا اشتغلوا بما لا يَعنيهم منها؛ فاتهم ما هو أعظمُ عنايةً لهم، وإذا عَدَّ غيرُهم الاشتغالَ بذلك وسماعَه من بابِ الظُّرْفِ والأدبِ وسَبْرِ الأحوال؛ كان هذا من خُدَعِ النفوسِ وتلبيسِها، فإنه يَحُطُّ الهِمَمَ العاليةَ من أَوْجِها إلى حَضِيضِها، ورُبَّما يعزُّ عليه أنْ يُحَصِّلَ هِمَّةً أخرى يصعدُ بها إلى موضعه الذي كان فيه، فأهلُ الهِمَمِ والفِطَنِ الثاقبةِ لا يفتحون من آذانهم وقلوبهم طريقًا إلى ذلك، إلَّا ما تقاضاه الأمرُ، وكانت مصلحتُه أرجحَ، وما عداه فبَطالةٌ، وحَطٌّ مرتبةٍ».', 0, 'احذر قطّاع الطريق إلى الله. (ص261–262)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1435, 147, 47, 'أنواع وصِيَغ الأوراد المأثورة', 0, '(ص263)', '', '', 'أنواع وصيغ الأوراد المأثورة', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1436, 147, 48, 'الأول: وِرْدُ القرآن الكريم.
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1443, 148, 1, 'النوع الأول: تلاوة القرآن الكريم', 0, '(ص265)', '', '', 'النوع الأول تلاوة القرآن الكريم', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1058, 148, 2, 'إنَّ تلاوة القرآن الكريم آكَدُ الأذكار، وأفضلها على الإطلاق، فلا يوجد ذِكرٌ يوازيه، فضلًا عن أن يكونَ أفضلَ منه، فينبغي المداومة عليها في كل حال: من ليلٍ ونهارٍ، سفرٍ أو حَضَرٍ، فلا يُخلِّي عنها يومًا وليلة، ولا يفرغ من ختمةٍ حتى يَصِلَها بأخرى.', 0, 'النوع الأول: تلاوة القرآن الكريم. (ص265)', '', '', 'إن تلاوة القرآن الكريم آكد الأذكار وأفضلها على الإطلاق فلا يوجد ذكر يوازيه فضلا عن أن يكون أفضل منه فينبغي المداومة عليها في كل حال من ليل ونهار سفر أو حضر فلا يخلي عنها يوما وليلة ولا يفرغ من ختمة حتى يصلها بأخرى', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1444, 148, 3, 'وما أفضلُ الأعمالِ إلا افتتاحُه مع الخَتْمِ حِلًّا وارتِحالًا مُوَصَّلًا', 0, 'النوع الأول: تلاوة القرآن الكريم. (ص265)', '', '', 'وما أفضل الأعمال إلا افتتاحه مع الختم حلا وارتحالا موصلا', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1445, 148, 4, 'قال الله تعالى: ﴿وَرَتِّلِ ٱلۡقُرۡءَانَ تَرۡتِيلًا﴾ الآية [المزمل: ٤].', 0, 'النوع الأول: تلاوة القرآن الكريم. (ص265)', '', '', 'قال الله تعالى ﴿ورتل ٱلۡقرۡءان ترۡتيلا﴾ الآية المزمل ٤', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1446, 148, 5, 'وقال الله عَزَّ وَجَلَّ: ﴿وَأُمِرۡتُ أَنۡ أَكُونَ مِنَ ٱلۡمُسۡلِمِينَ ۝ وَأَنۡ أَتۡلُوَاْ ٱلۡقُرۡءَانَ﴾ [النمل: ٩١، ٩٢].', 0, 'النوع الأول: تلاوة القرآن الكريم. (ص265)', '', '', 'وقال الله عز وجل ﴿وأمرۡت أنۡ أكون من ٱلۡمسۡلمين ۝ وأنۡ أتۡلوا ٱلۡقرۡءان﴾ النمل ٩١ ٩٢', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1059, 148, 6, 'وقال سبحانه: ﴿إِنَّ ٱلَّذِينَ يَتۡلُونَ كِتَٰبَ ٱللَّهِ وَأَقَامُواْ ٱلصَّلَوٰةَ وَأَنفَقُواْ مِمَّا رَزَقۡنَٰهُمۡ سِرّٗا وَعَلَانِيَةٗ يَرۡجُونَ تِجَٰرَةٗ لَّن تَبُورَ ۝ لِيُوَفِّيَهُمۡ أُجُورَهُمۡ وَيَزِيدَهُم مِّن فَضۡلِهِۦٓۚ إِنَّهُۥ غَفُورٞ شَكُورٞ﴾ [فاطر: ٢٩، ٣٠].', 0, 'النوع الأول: تلاوة القرآن الكريم. (ص265–266)', '', '', 'وقال سبحانه ﴿إن ٱلذين يتۡلون كتب ٱلله وأقاموا ٱلصلوة وأنفقوا مما رزقۡنهمۡ سرا وعلانية يرۡجون تجرة لن تبور ۝ ليوفيهمۡ أجورهمۡ ويزيدهم من فضۡلهۦۚ إنهۥ غفور شكور﴾ فاطر ٢٩ ٣٠', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1447, 148, 7, 'وحفلت السُّنَّةُ الشَّريفَةُ بالأحاديث التي تُوصِي بقراءة القرآن المجيد، وتبين فضائل تلاوته:', 0, 'النوع الأول: تلاوة القرآن الكريم. (ص266)', '', '', 'وحفلت السنة الشريفة بالأحاديث التي توصي بقراءة القرآن المجيد وتبين فضائل تلاوته', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1437, 149, 1, 'فعن أبي سعيدٍ الخدري رضي الله عنه أنَّ رسولَ الله ﷺ أوصاه، فقال: «... وعليكَ بِذِكرِ اللهِ وتلاوةِ القرآنِ، فإنَّه رُوحُكَ في السماء، وذِكرُكَ في الأرض».', 0, 'فضل تلاوة القرآن المجيد. (ص266)', '', '', 'فعن أبي سعيد الخدري رضي الله عنه أن رسول الله أوصاه فقال « وعليك بذكر الله وتلاوة القرآن فإنه روحك في السماء وذكرك في الأرض»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1060, 149, 2, 'وعن ابن مسعودٍ رضي الله عنه قال: قال رسول الله ﷺ: «مَن سَرَّه أن يُحِبَّ اللهَ ورسولَه، فليقرأ في المصحف».', 0, 'فضل تلاوة القرآن المجيد. (ص266)', '', '', 'وعن ابن مسعود رضي الله عنه قال قال رسول الله «من سره أن يحب الله ورسوله فليقرأ في المصحف»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1062, 149, 3, 'وعن أبي أمامةَ الباهليِّ رضي الله عنه قال: سمعتُ رسولَ الله ﷺ يقول: «اقرؤوا القرآنَ، فإنَّه يأتي يومَ القيامةِ شفيعًا لأصحابه، اقرؤوا الزَّهْرَاوَيْنِ: البقرةَ وآلَ عمران، فإنهما يأتيانِ يومَ القيامةِ كأنَّهما غَمامتان أو كأنهما غَيايتان، أو كأنهما فِرقانِ من طيرٍ صَوافَّ تُحاجَّانِ عن أصحابهما، اقرؤوا سورةَ البقرة، فإنَّ أخذَها بركةٌ، وتَرْكَها حسرةٌ، ولا يستطيعُها البَطَلَةُ».', 0, 'فضل تلاوة القرآن المجيد. (ص266–267)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1438, 149, 4, 'وعن أبي موسى الأشعري رضي الله عنه قال: قال رسول الله ﷺ: «مَثَلُ المؤمنِ الذي يقرأُ القرآنَ مَثَلُ الأُتْرُجَّةِ: ريحُها طَيِّبٌ وطَعْمُها طَيِّبٌ، ومثلُ المؤمنِ الذي لا يقرأُ القرآنَ كمثلِ التمرةِ: لا ريحَ لَها وطعمُها حُلْوٌ، ومثلُ المُنافقِ الذي يقرأُ القرآنَ كمثلِ الرَّيحانةِ: ريحُها طيِّبٌ وطعمُها مُرٌّ، ومثلُ المنافقِ الذي لا يقرأُ القرآنَ كمثلِ الحَنْظَلةِ: ريحُها مُرٌّ وطعمُها مُرٌّ».', 0, 'فضل تلاوة القرآن المجيد. (ص267–268)', '', '', 'وعن أبي موسى الأشعري رضي الله عنه قال قال رسول الله «مثل المؤمن الذي يقرأ القرآن مثل الأترجة ريحها طيب وطعمها طيب ومثل المؤمن الذي لا يقرأ القرآن كمثل التمرة لا ريح لها وطعمها حلو ومثل المنافق الذي يقرأ القرآن كمثل الريحانة ريحها طيب وطعمها مر ومثل المنافق الذي لا يقرأ القرآن كمثل الحنظلة ريحها مر وطعمها مر»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1063, 149, 5, 'وعن ابن مسعودٍ رضي الله عنه قال: قال رسول الله ﷺ: «من قَرَأَ حَرفًا من كتابِ الله، فَلَهُ به حسنة، والحسنةُ بعشرِ أمثالِها، لا أقول: ﴿الٓمٓ﴾ حرف، ولكن (ألفٌ) حرف، و(لامٌ) حرف، و(ميمٌ) حرف».', 0, 'فضل تلاوة القرآن المجيد. (ص268)', '', '', 'وعن ابن مسعود رضي الله عنه قال قال رسول الله «من قرأ حرفا من كتاب الله فله به حسنة والحسنة بعشر أمثالها لا أقول ﴿الم﴾ حرف ولكن ألف حرف و لام حرف و ميم حرف»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1064, 149, 6, 'وعن أمِّ المؤمنين عائشةَ رضي الله عنها، قالت: قال رسول الله ﷺ: «الماهرُ بالقرآنِ مع السَّفَرَةِ الكِرامِ البَرَرَةِ، والذي يَقْرأُ القرآنَ ويَتَتَعْتَعُ فيه، وهُوَ عليه شاقٌّ، له أجْرانِ». وفي لَفْظٍ آخَرَ: «والذي يَقْرَؤُه وهو يَشْتَدُّ عليه؛ فله أجْرانِ».', 0, 'فضل تلاوة القرآن المجيد. (ص268–269)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1439, 149, 7, 'وعن ابن عمر رضي الله عنهما عن النبي ﷺ قال: «لا حَسَدَ إلا في اثنتين: رجلٌ آتاه اللهُ القرآنَ، فهو يقوم به آناءَ الليل وآناءَ النهار، ورجلٌ آتاه الله مالًا، فهو يُنفِقُه آناءَ الليلِ وآناءَ النهارِ».', 0, 'فضل تلاوة القرآن المجيد. (ص269)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1067, 149, 8, 'وعن أمير المؤمنين عمر بن الخطاب رضي الله عنه أنَّ النبيَّ ﷺ قال: «إنَّ اللهَ يَرفعُ بهذا الكتابِ أقوامًا، ويَضَعُ آخرين».', 0, 'فضل تلاوة القرآن المجيد. (ص269)', '', '', 'وعن أمير المؤمنين عمر بن الخطاب رضي الله عنه أن النبي قال «إن الله يرفع بهذا الكتاب أقواما ويضع آخرين»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1068, 149, 9, 'وعن ابن مسعودٍ رضي الله عنه قال: قال رسول الله ﷺ: «القرآنُ شافعٌ مُشَفَّعٌ، وماحِلٌ مُصَدَّقٌ، مَن جعلَه أمامَه؛ قادَهُ إلى الجنةِ، ومَن جعلَه خلفَه؛ ساقَهُ إلى النار».', 0, 'فضل تلاوة القرآن المجيد. (ص270)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1069, 149, 10, 'وعن أبي هريرةَ رضي الله عنه قال: قال رسول الله ﷺ: «ما اجتمعَ قومٌ في بيتٍ من بُيوتِ اللهِ تعالى، يَتلُونَ كِتابَ اللهِ، ويَتَدارَسونَه بينَهم؛ إلَّا نَزَلتْ عليهمُ السَّكينةُ، وغَشِيَتْهمُ الرَّحمةُ، وحَفَّتْهمُ المَلائكةُ، وذَكَرَهمُ اللهُ فيمَن عِندَه».', 0, 'فضل تلاوة القرآن المجيد. (ص270)', '', '', 'وعن أبي هريرة رضي الله عنه قال قال رسول الله «ما اجتمع قوم في بيت من بيوت الله تعالى يتلون كتاب الله ويتدارسونه بينهم إلا نزلت عليهم السكينة وغشيتهم الرحمة وحفتهم الملائكة وذكرهم الله فيمن عنده»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1070, 149, 11, 'وعن أنس بن مالكٍ رضي الله عنه قال: قال رسول الله ﷺ: «إنَّ لِلهِ أهلين من النَّاسِ»، فقيل: مَنْ أهلُ اللهِ منهم؟ قال: «أهلُ القرآنِ، هم أهلُ اللهِ وخاصَّتُه».', 0, 'فضل تلاوة القرآن المجيد. (ص270)', '', '', 'وعن أنس بن مالك رضي الله عنه قال قال رسول الله «إن لله أهلين من الناس» فقيل من أهل الله منهم قال «أهل القرآن هم أهل الله وخاصته»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1440, 149, 12, 'وعن عثمانَ بنِ عفَّانَ رضي الله عنه قال: قال رسولُ الله ﷺ: «خَيْرُكُم مَنْ تَعَلَّمَ القرآنَ وعَلَّمَهُ»، وفي روايةٍ: «إنَّ أفضَلَكُم مَن تَعَلَّمَ القرآنَ وعَلَّمَهُ».', 0, 'فضل تلاوة القرآن المجيد. (ص271)', '', '', 'وعن عثمان بن عفان رضي الله عنه قال قال رسول الله «خيركم من تعلم القرآن وعلمه» وفي رواية «إن أفضلكم من تعلم القرآن وعلمه»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1441, 149, 13, 'فخيرُ المعلِّمين من يُعَلِّمُ القرآن، وخَيرُ المتعلمين من يتعلَّمُ القرآن.', 0, 'فضل تلاوة القرآن المجيد. (ص271)', '', '', 'فخير المعلمين من يعلم القرآن وخير المتعلمين من يتعلم القرآن', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1065, 149, 14, 'وعن ابن عمرو رضي الله عنهما قال: قال رسول الله ﷺ: «يقالُ لصاحبِ القرآن: اقرأْ وارقَ ورتِّلْ، كما كنتَ تُرَتِّلُ في دارِ الدنيا، فإنَّ منزِلَتَكَ عندَ آخرِ آيةٍ كنتَ تقرؤُها».', 0, 'فضل تلاوة القرآن المجيد. (ص271)', '', '', 'وعن ابن عمرو رضي الله عنهما قال قال رسول الله «يقال لصاحب القرآن اقرأ وارق ورتل كما كنت ترتل في دار الدنيا فإن منزلتك عند آخر آية كنت تقرؤها»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1066, 149, 15, 'وعن أبي سعيد الخدري رضي الله عنه مرفوعًا: «يُقالُ لصاحب القرآنِ إذا دخلَ الجنةَ: اقرأْ واصعد، فيقرأُ، ويَصْعَدُ بكلِّ آيةٍ درجةً، حتى يقرأَ آخرَ شيءٍ معه».', 0, 'فضل تلاوة القرآن المجيد. (ص271)', '', '', 'وعن أبي سعيد الخدري رضي الله عنه مرفوعا «يقال لصاحب القرآن إذا دخل الجنة اقرأ واصعد فيقرأ ويصعد بكل آية درجة حتى يقرأ آخر شيء معه»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1442, 149, 16, 'وعن أبي هريرةَ رضي الله عنه عن النبي ﷺ قال: «يجيءُ القرآنُ -وفي روايةٍ: صاحبُ القرآنِ- يومَ القيامةِ، فيقولُ: يا ربِّ حَلِّه، فيُلبَسُ تاجَ الكرامةِ، ثُمَّ يقولُ: يا ربِّ زِدْهُ، فيُلْبَسُ حُلَّةَ الكرامةِ، ثُمَّ يقولُ: يا ربِّ ارضَ عنه، فيَرْضَى عنه، فيُقال له: اقرأْ، وارقَ، ويُزادُ بكلِّ آيةٍ حسنةً».', 0, 'فضل تلاوة القرآن المجيد. (ص272)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1448, 165, 1, 'تحزيب القرآن المجيد', 0, '(ص273)', '', '', 'تحزيب القرآن المجيد', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1449, 165, 2, 'عن أمير المؤمنين عمر بن الخطاب رضي الله عنه، قال: قال رسول الله ﷺ: «مَن نامَ عن حِزْبِه، أوْ عن شَيءٍ منه، فَقَرَأَهُ فيما بيْنَ صلاةِ الفَجْرِ وصلاةِ الظُّهْرِ؛ كُتِبَ له كَأنَّما قَرَأَهُ مِنَ اللَّيْلِ».', 0, 'تحزيب القرآن المجيد. (ص273)', '', '', 'عن أمير المؤمنين عمر بن الخطاب رضي الله عنه قال قال رسول الله «من نام عن حزبه أو عن شيء منه فقرأه فيما بين صلاة الفجر وصلاة الظهر كتب له كأنما قرأه من الليل»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1450, 165, 3, 'فالحزبُ هنا حصة معينة من القرآن الكريم يتلوها المرء احتسابًا، ونلاحظ أنَّ رسولَ الله ﷺ في هذا الحديث أضاف الحزبَ إلى الشخص: «حزبه»، وأطلق ذلك، ولم يُقَيِّدْهُ بقدرٍ، ويُفْهَمُ من هذا أنَّ تحديدَ مقدارِ (الحزب) أمرٌ شخصي يخضَعُ لظروفِ كلِّ شخصٍ على حِدَة، وقد اختلفت مسالِكُ الصحابةِ رضي الله عنهم في المقدارِ اليومي الذي يقرؤونه من القرآن الكريم، وتفاوتت أحزابهم في هذا، وإنْ كان قد رُوِيَ عنهم أنهم كانوا يختمونه في سبعة أيَّامٍ.', 0, 'تحزيب القرآن المجيد. (ص273)', '', '', 'فالحزب هنا حصة معينة من القرآن الكريم يتلوها المرء احتسابا ونلاحظ أن رسول الله في هذا الحديث أضاف الحزب إلى الشخص «حزبه» وأطلق ذلك ولم يقيده بقدر ويفهم من هذا أن تحديد مقدار الحزب أمر شخصي يخضع لظروف كل شخص على حدة وقد اختلفت مسالك الصحابة رضي الله عنهم في المقدار اليومي الذي يقرؤونه من القرآن الكريم وتفاوتت أحزابهم في هذا وإن كان قد روي عنهم أنهم كانوا يختمونه في سبعة أيام', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1451, 165, 4, 'وَلِكُلِّ إنسانٍ أن يختارَ مُدَّةَ خَتْم القرآن بما يناسب ظروفه، ولكنَّ الأفضلَ ألَّا يزيد على أربعين يومًا، قال القرطبيُّ رحمه الله: «والأربعون مُدَّةُ الضُّعفاءِ وأُولِي الأشغال»، يلي ذلك الختمُ في ثلاثين يومًا، ثم عشرين، ثم خمسةَ عشرَ يومًا، ثم عشرةِ أيَّام، ثم أسبوع، ثم خمسةِ أيام، ثم ثلاثةِ أيام، وهذا أقصى حالات الاجتهاد الواردة، وفي الحديث: «لا يفقهُ من قرأ القرآنَ في أقلَّ مِنْ ثلاث».', 0, 'تحزيب القرآن المجيد. (ص274)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1452, 165, 5, 'قال في «مختصر منهاج القاصدين»: «وأَوْلَى الأمرِ: ما لا يمنع الإنسانَ من أشغالِه المهمة، ولا يؤذيه في بدنه، ولا يَفُوتُ معه الترتيلُ والفهمُ».', 0, 'تحزيب القرآن المجيد. (ص274)', '', '', 'قال في «مختصر منهاج القاصدين» «وأولى الأمر ما لا يمنع الإنسان من أشغاله المهمة ولا يؤذيه في بدنه ولا يفوت معه الترتيل والفهم»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1453, 165, 6, 'التحزيب بالسور التَّامَّة أَوْلَى من التجزئة بالحروف:', 0, '(ص275)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1454, 165, 7, 'فقد كان هديُ الصَّحابةِ رضي الله عنهم تحزيبَ القرآن سُوَرًا تامَّةً، ولا يُجَزِّبون السورةَ الواحدةَ، وربما قدَّروا الحزبَ بالآياتِ، فيقولون: «خمسون آية، ستون آية»، لكن لم يحزبوا بعدد الحروف.', 0, 'التحزيب بالسور التَّامَّة أَوْلَى من التجزئة بالحروف. (ص275)', '', '', 'فقد كان هدي الصحابة رضي الله عنهم تحزيب القرآن سورا تامة ولا يجزبون السورة الواحدة وربما قدروا الحزب بالآيات فيقولون «خمسون آية ستون آية» لكن لم يحزبوا بعدد الحروف', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1455, 165, 8, 'لا يليقُ بمسلمٍ أن يُخَلِّيَ يومَه وليلتَه مِن قراءةِ القرآنِ الكريم:', 0, '(ص275)', '', '', 'لا يليق بمسلم أن يخلي يومه وليلته من قراءة القرآن الكريم', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1456, 165, 9, 'لِما ثبت من فضلٍ جزيلٍ لِمَنْ يقرأُ كتابَ الله تعالى، والأصلُ في ذلك قوله تعالى: ﴿فَٱقۡرَءُواْ مَا تَيَسَّرَ مِنَ ٱلۡقُرۡءَانِ﴾ [المزمل: ٢٠].', 0, 'لا يليق بمسلم أن يخلي يومه وليلته من قراءة القرآن الكريم: (ص275)', '', '', 'لما ثبت من فضل جزيل لمن يقرأ كتاب الله تعالى والأصل في ذلك قوله تعالى ﴿فٱقۡرءوا ما تيسر من ٱلۡقرۡءان﴾ المزمل ٢٠', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1457, 165, 10, 'عن أمير المؤمنين عثمان بن عفان رضي الله عنه، قال: «لو أن قلوبنا طَهُرَتْ؛ ما شبعت من كلام ربنا، وإنِّي أكرَهُ أن يأتِيَ عَلَيَّ يومٌ لا أَنْظُرُ فيه في المصحف».', 0, 'لا يليق بمسلم أن يخلي يومه وليلته من قراءة القرآن الكريم: (ص276)', '', '', 'عن أمير المؤمنين عثمان بن عفان رضي الله عنه قال «لو أن قلوبنا طهرت ما شبعت من كلام ربنا وإني أكره أن يأتي علي يوم لا أنظر فيه في المصحف»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1458, 165, 11, 'ولا يليق بالمسلم ألَّا يبذلَ للقرآنِ الكريم إلَّا الفَضْلَةَ من وقته، فلا يقرب المصحفَ الشريف إلا في وقت «العُطْلَة»!', 0, 'لا يليق بمسلم أن يخلي يومه وليلته من قراءة القرآن الكريم: (ص276)', '', '', 'ولا يليق بالمسلم ألا يبذل للقرآن الكريم إلا الفضلة من وقته فلا يقرب المصحف الشريف إلا في وقت «العطلة»!', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1459, 165, 12, 'بل لا يليق بمسلمٍ أن يخلوَ يومُه من (وِرْدٍ) يوميٍّ يتلوه من القرآن الكريم، بل لا بُدَّ أن يكون (وردُكَ) من خصائص هُويتك، وكما تتضمن بطاقةُ هُوِيَّتِكَ بياناتِكَ الشخصيةَ الأساسَ من الاسم والميلاد والوظيفة والعنوان... إلخ؛ كذلك ينبغي أن تتضمن قدرَ (وردِكَ) اليومي من القرآن الكريم، كعلامةٍ مُميِّزة مما يخصُّ هُويتك ويُميِّزُها.', 0, 'لا يليق بمسلم أن يخلي يومه وليلته من قراءة القرآن الكريم: (ص276)', '', '', 'بل لا يليق بمسلم أن يخلو يومه من ورد يومي يتلوه من القرآن الكريم بل لا بد أن يكون وردك من خصائص هويتك وكما تتضمن بطاقة هويتك بياناتك الشخصية الأساس من الاسم والميلاد والوظيفة والعنوان إلخ كذلك ينبغي أن تتضمن قدر وردك اليومي من القرآن الكريم كعلامة مميزة مما يخص هويتك ويميزها', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1460, 165, 13, 'الاستماعُ للقرآن الكريم عبادة فاضلة، لكن لا تهجُرْ قراءتَه بنفسِكَ:', 0, '(ص277)', '', '', 'الاستماع للقرآن الكريم عبادة فاضلة لكن لا تهجر قراءته بنفسك', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1461, 165, 14, 'الاستماعُ للقرآن الكريم عبادةٌ عظيمةٌ، وهي سبب لرحمة الله؛ قال تعالى: ﴿وَإِذَا قُرِئَ ٱلۡقُرۡءَانُ فَٱسۡتَمِعُواْ لَهُۥ وَأَنصِتُواْ لَعَلَّكُمۡ تُرۡحَمُونَ﴾ [الأعراف: ٢٠٤].', 0, 'الاستماع للقرآن الكريم عبادة فاضلة، لكن لا تهجر قراءته بنفسك: (ص277)', '', '', 'الاستماع للقرآن الكريم عبادة عظيمة وهي سبب لرحمة الله قال تعالى ﴿وإذا قرئ ٱلۡقرۡءان فٱسۡتمعوا لهۥ وأنصتوا لعلكمۡ ترۡحمون﴾ الأعراف ٢٠٤', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1462, 165, 15, 'وقال سبحانه: ﴿وَإِذَا سَمِعُواْ مَآ أُنزِلَ إِلَى ٱلرَّسُولِ تَرَىٰٓ أَعۡيُنَهُمۡ تَفِيضُ مِنَ ٱلدَّمۡعِ مِمَّا عَرَفُواْ مِنَ ٱلۡحَقِّ﴾ الآية [المائدة: ٨٣].', 0, 'الاستماع للقرآن الكريم عبادة فاضلة، لكن لا تهجر قراءته بنفسك: (ص277)', '', '', 'وقال سبحانه ﴿وإذا سمعوا مآ أنزل إلى ٱلرسول ترى أعۡينهمۡ تفيض من ٱلدمۡع مما عرفوا من ٱلۡحق﴾ الآية المائدة ٨٣', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1463, 165, 16, 'ومع ذلك فإنَّ مِنَ الناسِ مَنْ يقتصرُ على سماعِ القرآنِ الكريم في الصلوات الجهرية، أو في إذاعةِ القرآنِ الكريم، أو غير ذلك، لكنه يهجر تلاوته بنفسه مع قدرتِه على ذلك، وهذا سببٌ للحرمان من الفضائل العظيمة الثابتة في القرآن والسُّنَّةِ لقراءة القرآن الكريم.', 0, 'الاستماع للقرآن الكريم عبادة فاضلة، لكن لا تهجر قراءته بنفسك: (ص277)', '', '', 'ومع ذلك فإن من الناس من يقتصر على سماع القرآن الكريم في الصلوات الجهرية أو في إذاعة القرآن الكريم أو غير ذلك لكنه يهجر تلاوته بنفسه مع قدرته على ذلك وهذا سبب للحرمان من الفضائل العظيمة الثابتة في القرآن والسنة لقراءة القرآن الكريم', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1464, 165, 17, 'أعطِ كُلَّ ذي حَقٍّ حقَّه:', 0, '(ص278)', '', '', 'أعط كل ذي حق حقه', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1465, 165, 18, 'على المكلَّف أن يراعيَ التوازنَ بين وظائفه الحياتية الدينية منها والدنيوية، ويراعي عند تحديد حزبه القرآني أن (يُفَصِّلَه) على قَدِّه ومقاسه تمامًا كما يفعل الحائك عندما يَخِيط له ثوبًا، ويؤلِّف بين المسؤوليات الملقاة على عاتقه، وحجم وقته المتاح، ويختار في التحزيب ما يجد له خِفَّةً ونشاطًا وعونًا على الثبات والمداومة، والأوفقَ الأحبَّ إلى قلبه، ولا يشق على نفسه مشقةً تُحدِثُ له مللًا وانقطاعًا.', 0, 'أعط كل ذي حق حقه: (ص278)', '', '', 'على المكلف أن يراعي التوازن بين وظائفه الحياتية الدينية منها والدنيوية ويراعي عند تحديد حزبه القرآني أن يفصله على قده ومقاسه تماما كما يفعل الحائك عندما يخيط له ثوبا ويؤلف بين المسؤوليات الملقاة على عاتقه وحجم وقته المتاح ويختار في التحزيب ما يجد له خفة ونشاطا وعونا على الثبات والمداومة والأوفق الأحب إلى قلبه ولا يشق على نفسه مشقة تحدث له مللا وانقطاعا', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1466, 165, 19, 'وَلْيَعرِفْ قَدْرَ نفسه بلا وَكْسٍ ولا شطط، ولا يُجازِفْ في تقدير قدراته، فإنَّ «مَنْ كَبَّرَ اللقمةَ غَصَّ فيها» وإنَّ المرْءَ لو تكلَّف ما لا يستطيعه فإنه يُضطرُّ إلى الإخلال والانقطاع عما عزم على فعله، وقليلٌ يدوم خيرٌ من كثير ينقطع.', 0, 'أعط كل ذي حق حقه: (ص278)', '', '', 'وليعرف قدر نفسه بلا وكس ولا شطط ولا يجازف في تقدير قدراته فإن «من كبر اللقمة غص فيها» وإن المرء لو تكلف ما لا يستطيعه فإنه يضطر إلى الإخلال والانقطاع عما عزم على فعله وقليل يدوم خير من كثير ينقطع', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1467, 165, 20, 'قال ﷺ: «خُذُوا مِنَ الأعمالِ ما تُطيقونَ؛ فإنَّ اللهَ لا يَمَلُّ حتَّى تَمَلُّوا، وإنَّ أحبَّ الأعمالِ عندَ اللهِ ما دامَ، وإنْ قَلَّ».', 0, 'أعط كل ذي حق حقه: (ص278)', '', '', 'قال «خذوا من الأعمال ما تطيقون فإن الله لا يمل حتى تملوا وإن أحب الأعمال عند الله ما دام وإن قل»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1468, 165, 21, 'وتحديدُ مقدارِ (الحزب) أمرٌ تنظيمي محض، الهدفُ منه المواظبةُ على قراءة القرآن وعدمُ هجره، فإذا وجد نشاطًا في بعض الليالي طَوَّلَ القراءةَ، وإن كَسِلَ قصرها، لكن لا يقل عن الحدِّ الأدنى من حزبه؛ كي تصبحَ قراءةُ القرآنِ الكريمِ عادةً يوميَّةً كسائر الوظائف التي لا يتخلَّى عنها تحت أيِّ ظرفٍ.', 0, 'أعط كل ذي حق حقه: (ص279)', '', '', 'وتحديد مقدار الحزب أمر تنظيمي محض الهدف منه المواظبة على قراءة القرآن وعدم هجره فإذا وجد نشاطا في بعض الليالي طول القراءة وإن كسل قصرها لكن لا يقل عن الحد الأدنى من حزبه كي تصبح قراءة القرآن الكريم عادة يومية كسائر الوظائف التي لا يتخلى عنها تحت أي ظرف', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1469, 165, 22, 'قال الشيخ علي بن أحمد بن عبد الدائم في شأنِ شيخه الإمام اليونيني رحمه الله: «كان للشيخ الفقيه أوراد؛ لو جاءَه مَلِكٌ من الملوك ما أخَّرها عن وقتها».', 0, 'أعط كل ذي حق حقه: (ص279)', '', '', 'قال الشيخ علي بن أحمد بن عبد الدائم في شأن شيخه الإمام اليونيني رحمه الله «كان للشيخ الفقيه أوراد لو جاءه ملك من الملوك ما أخرها عن وقتها»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1470, 165, 23, 'وإذا أردتَ أن تحافظَ على وِرْدِكَ القرآني اليومي؛ فإنَّ أعظَمَ ما يُعينك على الثبات والمداومة عليه أن تُعامِلَه معاملةَ صلاةِ الفريضة، فتمنحه الأولويةَ على ما عداه من المهام، وتحرص على الإتيان به في وقته، وتجزع عند فواته، ولا يهدأ بالُكَ حتى تؤدِّيَه، وإذا فاتك تحسَّرتَ على فواته، وذُقْتَ مرارةَ الحِرمان، وقَدَّرتَه دَيْنًا يتحتَّم عليك قضاؤه.', 0, 'أعط كل ذي حق حقه: (ص279–280)', '', '', 'وإذا أردت أن تحافظ على وردك القرآني اليومي فإن أعظم ما يعينك على الثبات والمداومة عليه أن تعامله معاملة صلاة الفريضة فتمنحه الأولوية على ما عداه من المهام وتحرص على الإتيان به في وقته وتجزع عند فواته ولا يهدأ بالك حتى تؤديه وإذا فاتك تحسرت على فواته وذقت مرارة الحرمان وقدرته دينا يتحتم عليك قضاؤه', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1471, 165, 24, 'قال الإمام المحقق ابن القيم رحمه الله: «ومن علامات صحة قلبه: أنه إذا فاته وِرْدُه؛ وَجَدَ لِفَوَاتِهِ أَلَمًا أعظمَ من تألُّمِ الحريصِ بفواتِ مالِه وفقدِه».', 0, 'أعط كل ذي حق حقه: (ص280)', '', '', 'قال الإمام المحقق ابن القيم رحمه الله «ومن علامات صحة قلبه أنه إذا فاته ورده وجد لفواته ألما أعظم من تألم الحريص بفوات ماله وفقده»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1472, 165, 25, 'ومما يعين على المداومة على الوِرْدِ أن يُخَصِّصَ له وقتًا متصلًا في قيام الليل، أو في مجلسٍ واحدٍ عَقِيبَ صلاةِ الصبح، وبعد الإتيانِ بأذكارِ الصباحِ، فقد كان عبدُ الرحمن ابن أبي ليلى إذا صَلَّى الصبحَ قرأ المصحفَ حتى تطلع الشمس، وكان ثابتٌ البُنانيُّ يفعلُ ذلك أيضًا.', 0, 'أعط كل ذي حق حقه: (ص280)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1473, 165, 26, 'فإنْ لم يناسِبْه ذلك؛ وَزَّعَ وِرْدَه على أوقاتٍ عِدَّةً خلالَ اليوم، أو يربطه بقبل الصلوات أو بعدها، أو كليهما.', 0, 'أعط كل ذي حق حقه: (ص280)', '', '', 'فإن لم يناسبه ذلك وزع ورده على أوقات عدة خلال اليوم أو يربطه بقبل الصلوات أو بعدها أو كليهما', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1474, 152, 1, 'النوع الثاني: وِرْدُ التهليل (لا إله إلا الله)', 0, '(ص281)', '', '', 'النوع الثاني ورد التهليل لا إله إلا الله', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1475, 152, 2, '«لا إله إلَّا الله» كلمة أمرها عظيم، وخَطْبُها جسيم، وشأنُها جليل، كلمةٌ على الله كريمة، ولها عنده سبحانه مكانٌ وشأن، أعلاها مُثْمِرٌ، وأسفلُها مُغْدِقٌ، لا توجد في الوجود كلمةٌ أصدقُ ولا أعظمُ ولا أطهر ولا أقدس ولا أشرفُ منها، وليس في الدنيا ولا في الآخرة كلمةٌ ثبت لها من الفضائل ما ثبت لها، فضائل لا يمكن عَدُّها وحَصْرُها؛ إذ يترتب عليها من الخير العميم، والأجرِ الجزيل، والثوابِ الجليل، ما لا يسنَحُ بخيال، ولا يخطرُ على بال.', 0, 'النوع الثاني: وِرْدُ التهليل (لا إله إلا الله). (ص281)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1476, 152, 3, '«لا إله إلا الله» كلمةُ الإسلام، ومِفتاحُ دارِ السلام، عنها يُسْأَلُ الأولون والآخِرون، فلا تزول قدما العبدِ بين يدي الله حتى يُسْأَلَ عن مسألتين: ماذا كنتم تعبدون؟ وماذا أجبتم المرسلين؟', 0, 'النوع الثاني: وِرْدُ التهليل (لا إله إلا الله). (ص282)', '', '', '«لا إله إلا الله» كلمة الإسلام ومفتاح دار السلام عنها يسأل الأولون والآخرون فلا تزول قدما العبد بين يدي الله حتى يسأل عن مسألتين ماذا كنتم تعبدون وماذا أجبتم المرسلين', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1477, 152, 4, 'فجوابُ الأولى: بتحقيق «لا إله إلا الله» معرفةً وإقرارًا وعملًا.', 0, 'النوع الثاني: وِرْدُ التهليل (لا إله إلا الله). (ص282)', '', '', 'فجواب الأولى بتحقيق «لا إله إلا الله» معرفة وإقرارا وعملا', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1478, 152, 5, 'وجوابُ الثانية: بتحقيق أنَّ «محمدًا رسولُ الله» معرفةً وإقرارًا، وانقيادًا وطاعةً.', 0, 'النوع الثاني: وِرْدُ التهليل (لا إله إلا الله). (ص282)', '', '', 'وجواب الثانية بتحقيق أن «محمدا رسول الله» معرفة وإقرارا وانقيادا وطاعة', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1479, 152, 6, '«لا إله إلا الله» تاجُ الموحِّدين، ونور أفئدة المتقين، وحصن الأمان، وسفينة النجاة، وكلمة الشهادة، ومِفتاحُ دارِ السعادة.', 0, 'النوع الثاني: وِرْدُ التهليل (لا إله إلا الله). (ص282)', '', '', '«لا إله إلا الله» تاج الموحدين ونور أفئدة المتقين وحصن الأمان وسفينة النجاة وكلمة الشهادة ومفتاح دار السعادة', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1480, 152, 7, 'بـ«لا إله إلا الله» أنزَلَ اللهُ الكتُبَ، وأرسَلَ الرُّسُلَ، وشرع الشرائع.', 0, 'النوع الثاني: وِرْدُ التهليل (لا إله إلا الله). (ص282)', '', '', 'ب«لا إله إلا الله» أنزل الله الكتب وأرسل الرسل وشرع الشرائع', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1481, 152, 8, '«لا إله إلا الله» أصلُ الدين وأساسُه، ورأسُ أمره، وساقُ شجرته، وعمودُ فُسطاطِه، وبقيةُ أركان الدين متفرعةٌ عنها، متشعبة منها، مكمِّلاتٌ لها، مقيَّدةٌ بالتزام معناها، والعمل بمقتضاها.', 0, 'النوع الثاني: وِرْدُ التهليل (لا إله إلا الله). (ص283)', '', '', '«لا إله إلا الله» أصل الدين وأساسه ورأس أمره وساق شجرته وعمود فسطاطه وبقية أركان الدين متفرعة عنها متشعبة منها مكملات لها مقيدة بالتزام معناها والعمل بمقتضاها', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1482, 152, 9, 'ومن أجل «لا إله إلا الله» نُصِبَتِ الموازينُ، ووُضِعَتِ الدَّواوينُ، وقام سُوقُ الجنَّةِ والنار، وهي التي فَرَّقتِ الناسَ إلى مؤمنين وكُفَّار، وميَّزتهم إلى السعداءِ أهلِ الجنَّةِ، والأشقياءِ أهلِ النار، وبها تكونُ السعادةُ والشقاوة، بل لا وصولَ للسعادةِ في الدَّارَيْنِ إلَّا بها.', 0, 'النوع الثاني: وِرْدُ التهليل (لا إله إلا الله). (ص283)', '', '', 'ومن أجل «لا إله إلا الله» نصبت الموازين ووضعت الدواوين وقام سوق الجنة والنار وهي التي فرقت الناس إلى مؤمنين وكفار وميزتهم إلى السعداء أهل الجنة والأشقياء أهل النار وبها تكون السعادة والشقاوة بل لا وصول للسعادة في الدارين إلا بها', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1483, 152, 10, 'وبها النجاةُ من النار بعد الوُرود، وبِعَدَمِ التزامِها البقاءُ فيها والخلود، بها تُؤخَذُ الكتبُ باليمين أو الشمال، ويثقل الميزان أو يخفُّ، وعنها يُسأَلُ الأوَّلون والآخِرون.', 0, 'النوع الثاني: وِرْدُ التهليل (لا إله إلا الله). (ص283)', '', '', 'وبها النجاة من النار بعد الورود وبعدم التزامها البقاء فيها والخلود بها تؤخذ الكتب باليمين أو الشمال ويثقل الميزان أو يخف وعنها يسأل الأولون والآخرون', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1484, 152, 11, '«لا إله إلَّا الله» أفضلُ الذِّكر بعد القرآن الكريم:', 0, '(ص284)', '', '', '«لا إله إلا الله» أفضل الذكر بعد القرآن الكريم', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1106, 152, 12, 'عن جابرِ بن عبد الله رضي الله عنهما، قال رسول الله ﷺ: «إنَّ أفضل الدعاء: الحمد لله، وأفضل الذكر: لا إله إلَّا الله».', 0, '«لا إله إلا الله» أفضل الذكر بعد القرآن الكريم. (ص284)', '', '', 'عن جابر بن عبد الله رضي الله عنهما قال رسول الله «إن أفضل الدعاء الحمد لله وأفضل الذكر لا إله إلا الله»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1485, 152, 13, 'وقوله ﷺ: «أفضلُ الذكر» أي بعد القرآن الكريم، لقوله ﷺ في حديث سمرة: «أفضلُ الكلامِ بعد القرآنِ أربعٌ، وهُنَّ من القرآن: سبحان الله، والحمدُ لله، ولا إله إلا الله، والله أكبر».', 0, '«لا إله إلا الله» أفضل الذكر بعد القرآن الكريم. (ص284)', '', '', 'وقوله «أفضل الذكر» أي بعد القرآن الكريم لقوله في حديث سمرة «أفضل الكلام بعد القرآن أربع وهن من القرآن سبحان الله والحمد لله ولا إله إلا الله والله أكبر»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1107, 152, 14, 'وعن أبي هريرةَ رضي الله عنه، قال رسول الله ﷺ: «أكثِروا من شهادة أن لا إله إلا الله، قبل أن يُحالَ بينكم وبينها، ولَقِّنوها موتاكم».', 0, '«لا إله إلا الله» أفضل الذكر بعد القرآن الكريم. (ص284)', '', '', 'وعن أبي هريرة رضي الله عنه قال رسول الله «أكثروا من شهادة أن لا إله إلا الله قبل أن يحال بينكم وبينها ولقنوها موتاكم»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1108, 152, 15, 'وعنه رضي الله عنه، قال رسول الله ﷺ: «من قال: (لا إله إلَّا الله)؛ نَفَعَتْهُ يومًا من دَهْرِه، يُصِيبه قبلَ ذلك ما أصابه».', 0, '«لا إله إلا الله» أفضل الذكر بعد القرآن الكريم. (ص284)', '', '', 'وعنه رضي الله عنه قال رسول الله «من قال لا إله إلا الله نفعته يوما من دهره يصيبه قبل ذلك ما أصابه»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1486, 69, 1, 'مِن صِيَغِ التهليل:', 0, '(ص285)', '', '', 'من صيغ التهليل', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (480, 69, 2, 'لا إله إلا الله.', 1, 'من صيغ التهليل. (ص285)', '', '', 'لا إله إلا الله', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (481, 69, 3, 'أشهدُ ألَّا إله إلا الله وحدَه، لا شريكَ له، وأشهدُ أنَّ محمدًا عبدُه ورسولُه، وأنَّ عيسى عبدُ اللهِ ورسُولُه، وكلمتُهُ ألقاها إلى مريمَ ورُوحٌ منه، وأنَّ الجنَّةَ حَقٌّ، والنَّارَ حَقٌّ.', 1, 'من صيغ التهليل. (ص285)', '', '', 'أشهد ألا إله إلا الله وحده لا شريك له وأشهد أن محمدا عبده ورسوله وأن عيسى عبد الله ورسوله وكلمته ألقاها إلى مريم وروح منه وأن الجنة حق والنار حق', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (482, 69, 4, 'لا إله إلا الله وحدَه، لا شريكَ له، اللهُ أكبرُ كبيرًا، والحمدُ لله كثيرًا، سبحانَ اللهِ رَبِّ العالمين، لا حولَ ولا قوَّةَ إلا بالله العزيزِ الحكيمِ، اللهم اغفِرْ لِي، وارحمني، واهدِني، وارزقني.', 1, 'من صيغ التهليل. (ص285)', '', '', 'لا إله إلا الله وحده لا شريك له الله أكبر كبيرا والحمد لله كثيرا سبحان الله رب العالمين لا حول ولا قوة إلا بالله العزيز الحكيم اللهم اغفر لي وارحمني واهدني وارزقني', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (483, 69, 5, 'اللهم إني أُشْهِدُكَ، وأُشْهِدُ ملائكتَك، وحَمَلَةَ عرشِكَ، وأُشْهِدُ مَن في السماواتِ ومَن في الأرض أنَّك أنتَ اللهُ، لا إله إلا أنتَ وحدَك، لا شريكَ لك، وأشهدُ أنَّ محمدًا عبدُكَ ورسولُك.', 3, 'من صيغ التهليل. [ثلاث مرات]. (ص285)', '', '', 'اللهم إني أشهدك وأشهد ملائكتك وحملة عرشك وأشهد من في السماوات ومن في الأرض أنك أنت الله لا إله إلا أنت وحدك لا شريك لك وأشهد أن محمدا عبدك ورسولك', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (484, 69, 6, 'لا إله إلا الله وحده، لا شريك له، له الملك، وله الحمد، وهو على كلِّ شيءٍ قدير.', 10, 'من صيغ التهليل. [عشر مرات، أو مئة مرة، أو أكثر]. (ص286)', '', '', 'لا إله إلا الله وحده لا شريك له له الملك وله الحمد وهو على كل شيء قدير', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1487, 161, 1, 'النوع الثالث: وِرْدُ الصلاة والسلام على سيِّد الأنام ﷺ', 0, '(ص287)', '', '', 'النوع الثالث ورد الصلاة والسلام على سيد الأنام', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1089, 161, 2, 'عن الأصمعي قال: سمعتُ المهديَّ على منبرِ البصرة يقول: «إنَّ اللهَ أمركم بأمرٍ بَدَأَ فيه بنفسه، وثنَّى بملائكته، فقال تشريفًا لنبيه وتكريمًا: ﴿إِنَّ ٱللَّهَ وَمَلَٰٓئِكَتَهُۥ يُصَلُّونَ عَلَى ٱلنَّبِيِّۚ يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ صَلُّواْ عَلَيۡهِ وَسَلِّمُواْ تَسۡلِيمًا﴾ [الأحزاب: ٥٦]، آثَرَه بها من بين الرسل الكرام، وأتحفكم بها من بين الأنام، فقابِلوا نعمتَه بالشكر، وأكثِروا مِنَ الصلاةِ عليه في الذِّكْرِ».', 0, 'النوع الثالث: وِرْدُ الصلاة والسلام على سيِّد الأنام ﷺ. (ص287)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1488, 161, 3, 'قال أبو العالية: «صلاةُ الله على نبيِّه: ثناؤه عليه وتعظيمه، وصلاةُ الملائكة وغيرهم عليه: طلبُ ذلك له من الله، والمرادُ طلبُ الزيادة، لا طلبُ أصل الصلاة».', 0, 'النوع الثالث: وِرْدُ الصلاة والسلام على سيِّد الأنام ﷺ. (ص287)', '', '', 'قال أبو العالية «صلاة الله على نبيه ثناؤه عليه وتعظيمه وصلاة الملائكة وغيرهم عليه طلب ذلك له من الله والمراد طلب الزيادة لا طلب أصل الصلاة»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1489, 161, 4, 'وقال ابن القيم: «... والصلاةُ المأمورُ بها في قوله تعالى: ﴿صَلُّواْ عَلَيۡهِ﴾ هي الطَّلَبُ من الله عَزَّ وَجَلَّ ما أخبر به عن صلاته وصلاةِ ملائكته، وهي: ثناءٌ عليه، وإظهارٌ لفضله وشرفه، وإرادةُ تكريمه وتقريبه، فهي تتضمن الخبرَ والطلب».', 0, 'النوع الثالث: وِرْدُ الصلاة والسلام على سيِّد الأنام ﷺ. (ص288)', '', '', 'وقال ابن القيم « والصلاة المأمور بها في قوله تعالى ﴿صلوا عليۡه﴾ هي الطلب من الله عز وجل ما أخبر به عن صلاته وصلاة ملائكته وهي ثناء عليه وإظهار لفضله وشرفه وإرادة تكريمه وتقريبه فهي تتضمن الخبر والطلب»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1490, 151, 1, 'عن أبي هريرةَ رضي الله عنه أنَّ رسول الله ﷺ قال: «ما قَعَدَ قومٌ مقعدًا لم يذكروا فيه الله عَزَّ وَجَلَّ ويُصلُّوا على النبي ﷺ إلَّا كان عليهم حسرةً يومَ القيامة، وإن دخلوا الجنةَ للثواب».', 0, 'النوع الثالث: وِرْدُ الصلاة والسلام على سيِّد الأنام ﷺ. (ص288)', '', '', 'عن أبي هريرة رضي الله عنه أن رسول الله قال «ما قعد قوم مقعدا لم يذكروا فيه الله عز وجل ويصلوا على النبي إلا كان عليهم حسرة يوم القيامة وإن دخلوا الجنة للثواب»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1491, 151, 2, 'وعنه رضي الله عنه قال: قال رسول الله ﷺ: «مَن ذُكِرتُ عنده فَنَسِيَ الصلاةَ عَلَيَّ، خُطِئَ طريقَ الجنَّةِ».', 0, 'النوع الثالث: وِرْدُ الصلاة والسلام على سيِّد الأنام ﷺ. (ص288)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1492, 151, 3, 'وعن أمير المؤمنين عليٍّ رضي الله عنه قال: قال رسول الله ﷺ: «البخيلُ مَنْ ذُكِرْتُ عِنْدَه، ثُمَّ لم يُصَلِّ عَلَيَّ».', 0, 'النوع الثالث: وِرْدُ الصلاة والسلام على سيِّد الأنام ﷺ. (ص288)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1493, 151, 4, 'فضلُ الصلاة والسلام على رسول الله ﷺ:', 0, '(ص289)', '', '', 'فضل الصلاة والسلام على رسول الله', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1494, 151, 5, 'عن أبي هريرةَ رضي الله عنه قال: قال رسول الله ﷺ: «ما مِنْ أحدٍ يُسَلِّمُ عَلَيَّ إلَّا رَدَّ اللهُ عَلَيَّ رُوحِي؛ حَتَّى أَرُدَّ عليه السلامَ».', 0, 'فضل الصلاة والسلام على رسول الله ﷺ. (ص289)', '', '', 'عن أبي هريرة رضي الله عنه قال قال رسول الله «ما من أحد يسلم علي إلا رد الله علي روحي حتى أرد عليه السلام»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1495, 151, 6, 'وعن سعيد بن عميرٍ الأنصاري عن أبيه رضي الله عنه قال: قال رسول الله ﷺ: «من صَلَّى عَلَيَّ مِنْ أُمَّتِي صلاةً مُخلِصًا مِنْ قَلْبِه؛ صَلَّى اللهُ عليه بها عَشْرَ صلواتٍ، ورَفَعَه بها عَشْرَ درجاتٍ، وكَتَبَ له بها عَشْرَ حسناتٍ، ومَحَا عَنْهُ عَشْرَ سيئاتٍ».', 0, 'فضل الصلاة والسلام على رسول الله ﷺ. (ص289)', '', '', 'وعن سعيد بن عمير الأنصاري عن أبيه رضي الله عنه قال قال رسول الله «من صلى علي من أمتي صلاة مخلصا من قلبه صلى الله عليه بها عشر صلوات ورفعه بها عشر درجات وكتب له بها عشر حسنات ومحا عنه عشر سيئات»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1496, 151, 7, 'وعن الطُّفَيْلِ بن أُبَيِّ بنِ كَعْبٍ، عن أبيه رضي الله عنه قال: كان رسول الله ﷺ إذا ذهبَ ثلثا الليل قام فقال: «يا أيها الناسُ، اذكروا اللهَ، جاءتِ الرَّاجِفَةُ تتبعُها الرَّادِفَةُ، جاءَ الموتُ بما فيه، جاءَ الموتُ بما فيه». قال أُبَيٌّ: قلتُ: يا رسول الله! إنِّي أُكْثِرُ الصلاةَ عليك، فَكَمْ أجعلُ لك مِن صلاتي، فقال: «ما شئتَ»، قال: قلتُ: الرُّبُعَ؟ قال: «ما شئتَ، فإنْ زِدْتَ فَهُوَ خيرٌ لَكَ»، قلتُ: النصف؟ قال: «ما شئتَ، فإنْ زِدْتَ فهو خيرٌ لك»، قال: قلت: فالثُّلُثَيْنِ؟ قال: «ما شئتَ، فإن زِدْتَ فهو خيرٌ لَكَ»، قلتُ: أجعلُ لكَ صلاتي كلَّها؟ قال: «إذَنْ تُكْفَى همَّك، ويُغْفَر لك ذَنْبُكَ». وفي روايةٍ: «إذَنْ يكفيك اللهُ هَمَّ الدُّنيا وهمَّ الآخِرَةِ».', 0, 'فضل الصلاة والسلام على رسول الله ﷺ. (ص289–291)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1497, 151, 8, 'والمعنى: أنَّكَ إذا صرفتَ جميعَ أزمانِ دعائك في الصلاة عليَّ أُعْطِيتَ مَرَامَ الدنيا والآخِرَةِ، وهذا غايةُ ما يدعو به الإنسانُ من جَلْبِ الخيراتِ، ودَفْعِ المَضَرَّاتِ، فإنَّ الدعاءَ فيه تحصيلُ المطلوب، واندفاعُ المرهوب.', 0, 'فضل الصلاة والسلام على رسول الله ﷺ. (ص291)', '', '', 'والمعنى أنك إذا صرفت جميع أزمان دعائك في الصلاة علي أعطيت مرام الدنيا والآخرة وهذا غاية ما يدعو به الإنسان من جلب الخيرات ودفع المضرات فإن الدعاء فيه تحصيل المطلوب واندفاع المرهوب', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1498, 151, 9, 'الصلاةُ على رسول الله ﷺ بين يَدَيِ الدعاء:', 0, '(ص291)', '', '', 'الصلاة على رسول الله بين يدي الدعاء', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1499, 151, 10, 'عن أمير المؤمنين عَلِيٍّ رضي الله عنه، قال رسول الله ﷺ: «كُلُّ دُعاءٍ مَحجُوبٌ حتى يُصَلَّى على النبيِّ ﷺ».', 0, 'الصلاة على رسول الله ﷺ بين يدي الدعاء. (ص291)', '', '', 'عن أمير المؤمنين علي رضي الله عنه قال رسول الله «كل دعاء محجوب حتى يصلى على النبي »', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1500, 151, 11, 'وعن أبي علي عمرو بن مالكٍ الجَنْبِيِّ: أنه سَمِعَ فَضَالَةَ بنَ عُبَيْدٍ يقول: سَمِعَ رسولُ الله ﷺ رجلًا يدعو في صلاته، لم يُحَمِّد الله، ولم يُصَلِّ على النبيِّ ﷺ، فقال النبيُّ ﷺ: «عَجِلَ هذا». ثُمَّ دعاهُ، فقال له: «إذا صَلَّى أحدُكم فَلْيَبدأْ بتحميد الله والثناء عليه، ثم لْيُصَلِّ على النبي ﷺ، ثُمَّ لْيَدْعُ بَعْدُ بما شاء».', 0, 'الصلاة على رسول الله ﷺ بين يدي الدعاء. (ص291)', '', '', 'وعن أبي علي عمرو بن مالك الجنبي أنه سمع فضالة بن عبيد يقول سمع رسول الله رجلا يدعو في صلاته لم يحمد الله ولم يصل على النبي فقال النبي «عجل هذا» ثم دعاه فقال له «إذا صلى أحدكم فليبدأ بتحميد الله والثناء عليه ثم ليصل على النبي ثم ليدع بعد بما شاء»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1501, 151, 12, 'الصلاةُ على النبي ﷺ ليلةَ الجمعةِ ويومَها:', 0, '(ص292)', '', '', 'الصلاة على النبي ليلة الجمعة ويومها', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1502, 151, 13, 'عن أنس بن مالكٍ رضي الله عنه، قال رسول الله ﷺ: «أكثِروا الصلاةَ عَلَيَّ يومَ الجمعةِ وليلةَ الجمعةِ، فَمَنْ صَلَّى عَلَيَّ صلاةً صَلَّى اللهُ عليه عَشْرًا».', 0, 'الصلاة على النبي ﷺ ليلة الجمعة ويومها. (ص292)', '', '', 'عن أنس بن مالك رضي الله عنه قال رسول الله «أكثروا الصلاة علي يوم الجمعة وليلة الجمعة فمن صلى علي صلاة صلى الله عليه عشرا»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1503, 70, 1, 'صِيَغُ الصَّلاةِ على رسول الله ﷺ:', 0, '(ص292)', '', '', 'صيغ الصلاة على رسول الله', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1504, 70, 2, 'تَقَدَّمَ ذكرُ ما صحَّ منها في «الصلاة على النبي ﷺ بعد التَّشَهُّد».', 0, 'صيغ الصلاة على رسول الله ﷺ. (ص292)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1505, 70, 3, 'تنبيه:', 0, '(ص292)', '', '', 'تنبيه', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1506, 70, 4, 'قال الإمام النووي رحمه الله بعد أن ذكر صِيَغَ الصَّلاةِ على النبي ﷺ السابقة: «وينبغي أن يجمع ما في الأحاديث الصحيحة السابقة، فيقول: اللهم صَلِّ على محمدٍ عبدِكَ ورسولِكَ النبيِّ الأُمِّيِّ، وعلى آلِ مُحَمَّدٍ وأزواجِه وذُرِّيَّتِه، كما صَلَّيتَ على إبراهيمَ وعلى آلِ إبراهيمَ، وبارِكْ على محمدٍ وعلى آلِ مُحَمَّدٍ وأزواجِه وذريتِه، كما باركتَ على إبراهيمَ، وعلى آلِ إبراهيمَ في العالمين، إنَّك حميدٌ مجيد».', 0, 'تنبيه. (ص292–293)
